mapper.select:
		SELECT

		FROM (SELECT * FROM STL_PAY_ORDERS D ORDER BY D.SETTLE_DATE DESC) S
		LEFT JOIN PTL_PORTFOLIO P ON S.PORTFOLIO_ID = P.PORTFOLIO_ID
		LEFT JOIN PTL_PORTFOLIO_AUTHORITY A ON A.PORTFOLIO_ID = P.PORTFOLIO_ID
		LEFT JOIN TRD_PRODUCT_DEAL T ON T.TRADE_ID = S.TRADE_ID


				AND (S.PORTFOLIO_ID IN

					#{item}

				    OR
				P.PARENT_PORTFOLIO_ID IN

					#{item}

				    )


				AND S.COUNTER_ACCT_NO = #{counterAcctNo}


				AND S.MY_ACCT_NO = #{myAcctNo}


				AND T.PS = #{payType}



                AND T.TRADE_STATUS = #{tradeStatus}


				AND S.SETTLE_DATE BETWEEN TO_DATE(#{dataDateStart},'YYYY-MM-DD')
				AND TO_DATE(#{dataDateEnd},'YYYY-MM-DD')


				AND A.USER_ID = #{userId}


				AND T.PS IN 

					#{item}



				AND T.IS_CANCEL = #{YES_OR_NO_N}

SELECT DISTINCT P.PORTFOLIO_ID id, P.PORTFOLIO_NAME text FROM PTL_PORTFOLIO P LEFT JOIN PTL_PORTFOLIO_AUTHORITY T ON T.PORTFOLIO_ID = P.PORTFOLIO_ID
AND T.USER_ID = #{userId}
AND (P.PORTFOLIO_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR P.PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))

SELECT P.ACCT_NO id, S.ACCT_NAME text
,S.SEQ_NO seqNo
FROM PTL_CAPACCT_INFO P LEFT JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO
AND (P.ACCT_NO LIKE CONCAT('%',CONCAT(#{search},'%')) OR S.ACCT_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))
AND P.PORTFOLIO_ID = #{portfolioId}
AND P.ACCT_TYPE = #{acctType}
AND P.ACCT_TYPE != #{oldAcctType}
AND P.CCY = #{ccy}

SELECT P.ACCT_NO id, S.ACCT_NAME text
,S.SEQ_NO seqNo
FROM PTL_CAPACCT_INFO P LEFT JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO
AND (P.ACCT_NO LIKE CONCAT('%',CONCAT(#{search},'%')) OR S.ACCT_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))
AND P.PORTFOLIO_ID = #{portfolioId}
AND P.ACCT_TYPE = #{acctType}
AND P.CCY = #{ccy}

SELECT 
	SEQNO
FROM 
	PTL_CASH_POSITION_FLOW


		AND ORDER_ID = #{tradeId}


		AND HODING_TYPE=#{hodeType}

SELECT ORDER_ID FROM STL_PAY_ORDERS
AND TRADE_ID = #{tradeId}
AND ROWNUM = 1
